attempts.refined_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance 
       (AVG(?avgProgress) AS ?avgProgressPct) 
       (AVG(?avgRisk) AS ?avgRiskScore) 
       (AVG(?avgLiquidity) AS ?avgLiquidityScore)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTolerance .

  {
    SELECT ?investorId (AVG(xsd:decimal(?p)) AS ?avgProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?p .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?r)) AS ?avgRisk) (AVG(xsd:decimal(?l)) AS ?avgLiquidity)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:investorId ?investorId ;
              wm:riskScore ?r ;
              wm:liquidityScore ?l .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

